        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: TestApp
settings:
  default_output: verbose
steps:
  test:
    command: "echo test"
"#,
        )
        .unwrap();

        // Local overrides
        fs::write(
            bivvy_dir.join("config.local.yml"),
            r#"
